    "gradeBand": "9-12",
    "overview": "Take apart two opinion pieces on the same question: should high school start later? Find each claim, weigh the evidence, and name the moves each writer makes.",
    "problems": [
      {
        "prompt": "State the central claim of each opinion piece in one precise sentence. Where in each piece is the claim stated most directly?"
      },
      {
        "prompt": "List two pieces of evidence the author of \"Let Teenagers Sleep\" uses. For each, say whether it is relevant to the claim and whether you think it is sufficient. Explain."
      },
      {
        "prompt": "List two pieces of evidence or reasons the author of \"A Later Bell Is Not a Free Lunch\" uses. For each, explain how it supports the claim."
      },
      {
        "prompt": "Each author addresses the other side. Quote the sentence where each writer concedes a point, then explain how the writer answers it."
      },
      {
        "prompt": "Find one example of rhetoric in either piece: a word choice, image, repetition or appeal meant to move the reader. Quote it and explain what it is meant to make the reader feel or believe."
      },
      {
        "prompt": "Which piece makes the stronger argument? Judge by the quality of the evidence and reasoning, not by which side you agree with. Name one claim in that piece you would want to check before trusting it."
      }
    ],
    "resources": [
      "later-bell-for",
      "later-bell-against"
    ],
    "showWork": false,
    "subject": "english-language-arts",
    "template": "problem-set",
    "title": "Anatomy of an Argument"
  },
  "alignments": [
    {
      "competencyUri": "urn:educateos:catalog:ccss-ela:CCSS.ELA-LITERACY.RI.9-10.8",
      "frameworkKey": "ccss-ela"
